const express = require('express');
const cors = require('cors');
const { v4: uuidv4 } = require('uuid');

// Create an Express app
const app = express();

app.use(cors());
app.use(express.json());

let todos = [
  {
    id: '1',
    title: 'Learn Node.js',
    completed: false,
    createdAt: new Date().toISOString(),
    updatedAt: new Date().toISOString()
  }
];

/**
 * GET /todos
 * List all todos with optional filtering by completion status.
 */
app.get('/todos', (req, res) => {
  try {
    const filter = req.query.completed === 'true';
    if (filter !== undefined && typeof filter !== 'boolean') {
      return res.status(400).json({ error: 'Invalid filter parameter' });
    }

    const filteredTodos = filter 
      ? todos.filter(todo => todo.completed)
      : todos;

    // Sort by createdAt descending
    filteredTodos.sort((a, b) => new Date(b.createdAt) - new Date(a.createdAt));

    res.json(filteredTodos);
  } catch (error) {
    console.error('Error getting todos:', error);
    res.status(500).json({ error: 'Internal server error' });
  }
});

/**
 * GET /todos/:id
 * Get a single todo by ID.
 */
app.get('/todos/:id', (req, res) => {
  try {
    const id = req.params.id;
    const todo = todos.find(todo => todo.id === id);

    if (!todo) {
      return res.status(404).json({ error: 'Todo not found' });
    }

    res.json(todo);
  } catch (error) {
    console.error('Error getting todo:', error);
    res.status(50="Internal server error");
  }
});

/**
 * POST /todos
 * Create a new todo. Validates title requirement and format.
 */
app.post('/todos', (req, res) => {
  try {
    const { title } = req.body;

    if (!title || typeof title !== 'string' || title.length < 1 || title.length > 100) {
      return res.status(400).json({ error: 'Title is required and must be a string between 1-100 characters' });
    }

    const newTodo = {
      id: uuidv4(),
      title,
      completed: false,
      createdAt: new Date().toISOString(),
      updatedAt: new Date().toISOString()
    };

    todos.push(newTodo);

    // Update the updatedAt field for the newly created todo
    newTodo.updatedAt = new Date().toISOString();

    res.status(201).json({
      todo: {
        id: newTodo.id,
        title: newTodo.title,
        completed: newTodo.completed,
        createdAt: newTodo.createdAt,
        updatedAt: newTodo.updatedAt
      }
    });
  } catch (error) {
    console.error('Error creating todo:', error);
    res.status(500).json({ error: 'Internal server error' });
  }
});

/**
 * PUT /todos/:id
 * Update a todo by ID. Validates title and completed status if provided.
 */
app.put('/todos/:id', (req, res) => {
  try {
    const id = req.params.id;
    const updates = req.body;

    // Find the todo to update
    const todoIndex = todos.findIndex(todo => todo.id === id);

    if (todoIndex === -1) {
      return res.status(404).json({ error: 'Todo not found' });
    }

    // Validate and update title if provided
    if (updates.title !== undefined) {
      if (typeof updates.title !== 'string' || updates.title.length < 1 || updates.title.length > 100) {
        return res.status(400).json({ error: 'Title must be a string between 1-100 characters' });
      }
      todos[todoIndex].title = updates.title;
    }

    // Validate and update completed status if provided
    if (updates.completed !== undefined) {
      if (typeof updates.completed !== 'boolean') {
        return res.status(400).json({ error: 'Completed must be a boolean' });
      }
      todos[todoIndex].completed = updates.completed;
    }

    // Update the updatedAt field with current time
    todos[todoIndex].updatedAt = new Date().toISOString();

    const updatedTodo = {
      id: todos[todoIndex].id,
      title: todos[todoIndex].title,
      completed: todos[todoIndex].completed,
      createdAt: todos[todoIndex].createdAt,
      updatedAt: todos[todoIndex].updatedAt
    };

    res.json({ todo: updatedTodo });
  } catch (error) {
    console.error('Error updating todo:', error);
    res.status(500).json({ error: 'Internal server error' });
  }
});

/**
 * DELETE /todos/:id
 * Delete a todo by ID.
 */
app.delete('/todos/:id', (req, res) => {
  try {
    const id = req.params.id;

    // Find the index of the todo to delete
    const todoIndex = todos.findIndex(todo => todo.id === id);

    if (todoIndex === -1) {
      return res.status(404).json({ error: 'Todo not found' });
    }

    todos.splice(todoIndex, 1); // Remove the todo from array

    res.json({
      message: 'Todo deleted successfully',
      deletedId: id
    });
  } catch (error) {
    console.error('Error deleting todo:', error);
    res.status(500).json({ error: 'Internal server error' });
  }
});

